        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no filtering keys are supplied, simply return all values.
        if not keys:
            return list(self._data.values())

        key_sequence = list(self._data.keys())
        result = []

        for k in keys:
            # Determine whether k is an index or a key.
            if isinstance(k, int):
                try:
                    key = key_sequence[k]
                except IndexError as exc:
                    raise IndexError(
                        f"Index {k} is out of range for record of length {len(key_sequence)}"
                    ) from exc
            else:
                if k not in self._data:
                    raise KeyError(f"Key {k!r} not found in record")
                key = k

            result.append(self._data[key])

        return result

