def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure internal structures exist
    if not hasattr(self, "_values"):
        raise AttributeError("Record object has no '_values' attribute")
    if not hasattr(self, "_keys"):
        raise AttributeError("Record object has no '_keys' attribute")

    values = self._values
    keys_list = self._keys

    # Build key-to-index map lazily if not present
    if not hasattr(self, "_key_to_index"):
        self._key_to_index = {k: idx for idx, k in enumerate(keys_list)}

    key_to_index = self._key_to_index

    if not keys:
        # Return all items
        return dict(zip(keys_list, values))

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            if key < 0 or key >= len(values):
                raise IndexError(f"Index {key} is out of bounds")
            result[keys_list[key]] = values[key]
        # Handle key strings (or non-integer keys)
        else:
            if key in key_to_index:
                idx = key_to_index[key]
                result[key] = values[idx]
            else:
                # key not found: insert None
                result[key] = None
    return result

