def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """

    def __init__(self, *args, **kwargs):
        # Initialize the base Point class if it requires
        try:
            super(self.__class__, self).__init__(*args)
        except TypeError:
            pass  # if Base doesn't accept args
        # Set attributes defined in fields
        for field in fields:
            value = kwargs.get(field, None)
            setattr(self, field, value)

    # Build class dictionary with custom __init__ and SRID mapping
    cls_attrs = {
        "__init__": __init__,
        "_srid_map": srid_map,
    }

    # Return a new subclass of Point with the specified name
    return type(name, (Point,), cls_attrs)

