def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures
    import os
    import shlex

    # Partition the arguments so that each command invocation stays within *_max_length.
    # We approximate the command length as the sum of the argument lengths plus a few
    # spaces and potential quoting characters.
    partitions: list[list[str]] = []
    current_partition: list[str] = []

    def current_partition_length(args: list[str]) -> int:
        # Rough estimate: joining with spaces plus quoting each argument
        joined = shlex.join([*cmd, *args])
        return len(joined)

    for item in varargs:
        # Try to add item to current partition; if it would exceed the limit, start a new partition.
        if current_partition:
            new_length = current_partition_length(current_partition + [item])
            if new_length > _max_length:
                partitions.append(current_partition)
                current_partition = [item]
            else:
                current_partition.append(item)
        else:
            # first item in the partition
            current_partition = [item]

    if current_partition:
        partitions.append(current_partition)

    # Function that runs a single partition and returns (returncode, stdout+stderr)
    def run_partition(part: list[str]) -> tuple[int, bytes]:
        # Decide whether to use a pty for color output
        if color and os.isatty(0):
            # On POSIX systems we can use a dummy pty; on Windows we ignore color
            pty_pipe = subprocess.PIPE
            run_kwargs = {"stdout": pty_pipe, "stderr": pty_pipe}
        else:
            run_kwargs = {}

        # Merge user-provided kwargs, giving priority to explicit ones for stdout/stderr handling
        merged_kwargs = {**kwargs, **run_kwargs}

        # Execute the command
        result = subprocess.run(list(cmd) + part, **merged_kwargs)
        # Capture stdout and stderr if they were combined via PIPE or UNCHANGED
        output = b""
        if result.stdout:
            output += result.stdout
        if result.stderr:
            output += result.stderr
        return result.returncode, output

    # Run the partitions concurrently
    max_workers = max(1, target_concurrency)
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_part = {executor.submit(run_partition, p): p for p in partitions}
        overall_exit = 0
        combined_output = bytearray()
        for future in concurrent.futures.as_completed(future_to_part):
            rc, out = future.result()
            combined_output.extend(out)
            if rc != 0 and overall_exit == 0:
                overall_exit = rc

    return overall_exit, bytes(combined_output)

