def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts: list[int] = []
    current = ""
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                parts.append(int(current))
                current = ""
    if current:
        parts.append(int(current))
    return tuple(parts)

