def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute the cache key
            try:
                k = key(*args, **kwargs)
            except TypeError:
                # If key function doesn't accept *args, **kwargs directly,
                # try passing a single tuple/dict
                k = key((args, kwargs))
            # Use the lock if provided for thread safety
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

