def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        from threading import RLock
        cache = {}
        usage = []  # list of keys for LRU ordering
        lock = RLock()

        def _make_key(*args, **kwargs):
            if typed:
                key_args = tuple((arg, type(arg)) for arg in args)
                key_kwargs = tuple((k, (v, type(v))) for k, v in sorted(kwargs.items()))
            else:
                key_args = tuple(args)
                key_kwargs = tuple(sorted(kwargs.items()))
            return (key_args, key_kwargs)

        def wrapper(*args, **kwargs):
            key = _make_key(*args, **kwargs)
            now = timer()
            with lock:
                if key in cache:
                    value, expire_at = cache[key]
                    if expire_at is None or now < expire_at:
                        # refresh LRU order
                        try:
                            usage.remove(key)
                        except ValueError:
                            pass
                        usage.append(key)
                        return value
                    # expired
                    del cache[key]
                    try:
                        usage.remove(key)
                    except ValueError:
                        pass
                # compute new value
                result = func(*args, **kwargs)
                expire_at = None if ttl <= 0 else now + ttl
                cache[key] = (result, expire_at)
                usage.append(key)
                if len(cache) > maxsize:
                    oldest_key = usage.pop(0)
                    cache.pop(oldest_key, None)
                return result

        return wrapper

    return decorator

