def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    from collections import OrderedDict
    def decorating_function(user_function):
        cache = OrderedDict()
        def _make_key(args, kwargs):
            if typed:
                key = []
                for a in args:
                    key.append((a, type(a)))
                for k in sorted(kwargs):
                    v = kwargs[k]
                    key.append((k, (v, type(v))))
                return tuple(key)
            else:
                return args + tuple(sorted(kwargs.items()))
        def wrapper(*args, **kwds):
            if maxsize == 0:
                return user_function(*args, **kwds)
            key = _make_key(args, kwds)
            if key in cache:
                cache.move_to_end(key)
                return cache[key]
            result = user_function(*args, **kwds)
            if len(cache) >= maxsize:
                cache.popitem(last=True)  # evict most recently used
            cache[key] = result
            return result
        wrapper.cache_clear = lambda: cache.clear()
        def cache_info():
            """Return cache statistics:
            (hits, misses, maxsize, currsize)"""
            return (0, 0, maxsize, len(cache))
        wrapper.cache_info = cache_info
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        wrapper.__wrapped__ = user_function
        return wrapper
    return decorating_function

