@classmethod
def _reset_logging(cls):
    """
    Reset the logging configuration to its default state.
    This removes all existing handlers from the root logger
    and resets its level to WARNING.
    """
    # Import logging if it hasn't been imported elsewhere
    try:
        import logging
    except Exception:
        # If logging cannot be imported, nothing to reset
        return

    root_logger = logging.getLogger()
    # Detach all handlers
    for handler in root_logger.handlers[:]:
        try:
            root_logger.removeHandler(handler)
        except Exception:
            # In case a handler cannot be removed, continue gracefully
            pass
    # Reset the root logger level to WARNING (default)
    root_logger.setLevel(logging.WARNING)

