def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Priority: self._interface (dict), then self.interface, fallback to instance dict without private keys
    interface = getattr(self, "_interface", None) or getattr(self, "interface", None)
    if interface is None:
        # Default behaviour: use public attributes from the instance
        return [k for k in self.__dict__ if not k.startswith("_")]

    if all:
        # Include names from all interfaces if present
        interfaces = getattr(self, "_interfaces", [])
        names = set(interface.keys())
        for iface in interfaces:
            if isinstance(iface, dict):
                names.update(iface.keys())
        return sorted(names)

    return sorted(interface.keys())

