        # Preserve the original bin structure but replace all values
        if isinstance(self.bins, dict):
            self.bins = {k: self.initial_value for k in self.bins}
        else:
            try:
                # Preserve the length of an iterable (list, tuple, etc.)
                self.bins = [self.initial_value] * len(self.bins)
            except Exception:
                # Fallback: rebuild from scratch with make_bins()
                self.bins = self.make_bins()
    else:
        # Create a fresh bin configuration
        self.bins = self.make_bins()

