def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    and a new line is added automatically.

    A graph can be multidimensional: for each point first its coordinate
    is converted to string (values separated by *separator*), then each
    part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    # Assume the graph object exposes an iterable of (coord, value) pairs
    try:
        points_iterable = self.points  # primary attribute
    except AttributeError:
        try:
            points_iterable = self.data  # fallback
        except AttributeError:
            # If nothing is found, nothing to serialize
            return "\n".join(lines)

    for point in points_iterable:
        # Expect a tuple (coord, value)
        if not isinstance(point, (tuple, list)) or len(point) != 2:
            continue
        coord, value = point

        # Convert coordinate to string
        if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)

        # Convert value to string
        if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            value_str = separator.join(map(str, value))
        else:
            value_str = str(value)

        lines.append(coord_str + separator + value_str)

    return "\n".join(lines)

