def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If `seq` is explicitly a Source sequence, return False
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        pass  # `Source` not defined; ignore

    # If `seq` itself is a FillRequest instance, it's a match
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        pass  # `FillRequest` not defined; ignore

    # If `seq` is not iterable, we cannot contain a FillRequest
    try:
        iter(seq)
    except TypeError:
        return False

    # Iterate through the sequence and look for a FillRequest
    for item in seq:
        try:
            if isinstance(item, FillRequest):
                return True
        except NameError:
            pass  # `FillRequest` not defined; ignore

        # In some contexts a FillRequest might be represented as a dict
        if isinstance(item, dict) and item.get('type') == 'FillRequest':
            return True

    # No FillRequest found
    return False

