    if isinstance(observer_schema, dict):
        # Ensure last_applied_manifest is a dict
        if not isinstance(last_applied_manifest, dict):
            # Cannot rebuild a dict from a non-dict; nothing to do
            return
        for key, subschema in observer_schema.items():
            # Get the corresponding value from the response
            if not isinstance(response, dict):
                continue
            if key not in response:
                continue
