            # Initialize the field in the last_applied_manifest if absent
            if key not in last_applied_manifest:
                if isinstance(resp_value, (dict, list)):
                    last_applied_manifest[key] = {} if isinstance(resp_value, dict) else []
                else:
                    last_applied_manifest[key] = resp_value

            # Recurse if the schema indicates nested structure
            if isinstance(subschema, (dict, list)) and resp_value is not None:
                # Ensure the current value in last_applied_manifest matches the expected type
                if not isinstance(last_applied_manifest[key], type(subschema)):
                    last_applied_manifest[key] = {} if isinstance(subschema, dict) else []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], subschema, resp_value
                )
    elif isinstance(observer_schema, list):
        # Ensure last_applied_manifest is a list
        if not isinstance(last_applied_manifest, list):
            # Cannot rebuild a list from a non-list; nothing to do
            return
        for idx, subschema in enumerate(observer_schema):
            if not isinstance(response, list) or idx >= len(response):
                break
            resp_item = response[idx]

            # Extend the list if necessary
            if idx >= len(last_applied_manifest):
                if isinstance(resp_item, (dict, list)):
                    last_applied_manifest.append(
                        {} if isinstance(resp_item, dict) else []
                    )
                else:
                    last_applied_manifest.append(resp_item)

            # If the list item is None, initialize it
            if last_applied_manifest[idx] is None:
                if isinstance(resp_item, (dict, list)):
                    last_applied_manifest[idx] = {} if isinstance(resp_item, dict) else []
                else:
                    last_applied_manifest[idx] = resp_item

            # Recurse for nested structures
