                    last_applied_manifest[idx] = {} if isinstance(subschema, dict) else []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[idx], subschema, resp_item
                )
    else:
        # For primitive observer_schema, nothing to do; handled in parent call
        pass

    return last_applied_manifest

