def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    if path is None:
        path = getattr(self, "root", None)
    if path is None or not os.path.isdir(path):
        return False

    # Required top‑level files for a minimal OCFL object
    required_files = [".ocfl_version", "index.json"]
    for req in required_files:
        if not os.path.isfile(os.path.join(path, req)):
            return False

    # Verify the OCFL version is supported
    try:
        with open(os.path.join(path, ".ocfl_version"), "r", encoding="utf-8") as fp:
            version = fp.read().strip()
        if version not in ("4.0", "5.0", "6.0"):
            return False
    except Exception:
        return False

    # Attempt to parse the index.json to catch malformed JSON
    try:
        with open(os.path.join(path, "index.json"), "r", encoding="utf-8") as fp:
            json.load(fp)
    except Exception:
        return False

    # Optional checks: ensure artifact directories exist if they are listed
    try:
        root_path = os.path.join(path, "objects")
        for dirpath, dirs, files in os.walk(root_path):
            if ".ocfl-obj" in files:
                # Basic check that this dir contains a .ocfl-obj index
                if not os.path.isfile(os.path.join(dirpath, ".ocfl-obj")):
                    return False
        # If the objects directory is present and empty, that's acceptable
    except Exception:
        # Non‑existent objects directory is fine for minimal objects
        pass

    return True

