def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is a compatible validator instance
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an InventoryValidator instance")

    # Extract inventories
    inv_self = getattr(self, "inventory", None)
    inv_prior = getattr(prior, "inventory", None)

    if inv_self is None or inv_prior is None:
        raise ValueError("Both current and prior inventory objects must be available")

    # Helper to fetch a value via common attribute names
    def _get_attr(obj, names):
        for name in names:
            if hasattr(obj, name):
                return getattr(obj, name)
        # Try treating obj as a dict
        if isinstance(obj, dict):
            for name in names:
                if name in obj:
                    return obj[name]
        raise AttributeError(f"Unable to find attribute {names!r} in {obj!r}")

    # Get identifiers
    try:
        id_self = _get_attr(inv_self, ("id", "ID", "Id", "identifier", "Identifier"))
        id_prior = _get_attr(inv_prior, ("id", "ID", "Id", "identifier", "Identifier"))
    except AttributeError as exc:
        raise ValueError("Inventory objects must have an identifier") from exc

    # Identify revision numbers
    try:
        rev_self = _get_attr(inv_self, ("revision", "rev", "Revision", "Rev"))
        rev_prior = _get_attr(inv_prior, ("revision", "rev", "Revision", "Rev"))
    except AttributeError as exc:
        raise ValueError("Inventory objects must have a revision number") from exc

    # Ensure identifiers match
    if id_self != id_prior:
        raise ValueError("Prior inventory does not belong to the same entity as the current inventory")

    # Convert revisions to integers if possible
    def _to_int(val):
        if isinstance(val, int):
            return val
        if isinstance(val, float):
            # Reject non‑whole numbers
            if val.is_integer():
                return int(val)
            raise ValueError(f"Revision number must be an integer, got {val!r}")
        if isinstance(val, str) and val.isdigit():
            return int(val)
        raise ValueError(f"Revision number must be an integer representation, got {val!r}")

    rev_self_int = _to_int(rev_self)
    rev_prior_int = _to_int(rev_prior)

    # Prior revision must be strictly older
    if rev_prior_int >= rev_self_int:
        raise ValueError(
            f"Prior inventory revision ({rev_prior_int}) must be less than current revision ({rev_self_int})"
        )

    # If all checks pass, return None (successful validation)
    return None

