def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure inventory is a mapping and contains the requested version
    if not isinstance(inventory, dict) or version not in inventory:
        return {}

    version_entry = inventory[version]

    # Handle the case where the version entry is itself a mapping of logical path -> content(s)
    if isinstance(version_entry, dict):
        source_iter = version_entry.items()
    # Handle the case where the version entry might be a list/tuple of (logical_path, content) pairs
    elif isinstance(version_entry, (list, tuple)):
        source_iter = version_entry
    else:
        # If the data structure is unknown, return empty mapping
        return {}

    logical_path_map = {}
    for logical_path, content in source_iter:
        # Normalize content into a set of files
        if isinstance(content, (set, list, tuple)):
            content_files = set(content)
        elif content is None:
            content_files = set()
        else:
            content_files = {content}
        logical_path_map[logical_path] = content_files

    return logical_path_map

