def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Convert manifest list to a set for fast lookup
    manifest_set = set(manifest_files)

    # Determine the actual list of checksum entries
    if isinstance(fixity, dict):
        # Common keys are 'checksums' or 'file_checksums'
        checksums = fixity.get('checksums') or fixity.get('file_checksums')
        if checksums is None:
            raise ValueError("Fixity block must contain a 'checksums' or 'file_checksums' list.")
        if not isinstance(checksums, list):
            raise ValueError("'checksums' should be a list.")
    elif isinstance(fixity, list):
        checksums = fixity
    else:
        raise ValueError("Fixity block must be a dictionary or a list.")

    # Validate each entry
    for entry in checksums:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in the fixity block must be a dictionary.")
        if 'path' not in entry:
            raise ValueError("Missing 'path' in a fixity entry.")
        if 'checksum' not in entry:
            raise ValueError("Missing 'checksum' in a fixity entry.")

        file_path = entry['path']
        if file_path not in manifest_set:
            raise ValueError(f"Fixity references unknown file: {file_path}")

    return True

