def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        # Maintain a set of object ids to detect recursion
        seen = set()

        def _pretty(obj, depth):
            # Detect recursive references
            if isinstance(obj, (dict, list, tuple, set)):
                obj_id = id(obj)
                if obj_id in seen:
                    return '... (recursive reference)'
                seen.add(obj_id)

            # Pretty‑print dictionaries
            if isinstance(obj, dict):
                items = []
                for key in sorted(obj, key=lambda k: str(k)):
                    value = obj[key]
                    items.append(f"{'  ' * (depth + 1)}{repr(key)}: {_pretty(value, depth + 1)}")
                return f"{{\n" + ",\n".join(items) + f"\n{'  ' * depth}}}"

            # Pretty‑print lists, tuples, and sets
            if isinstance(obj, (list, tuple, set)):
                open_sym = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
                close_sym = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
                items = [f"{'  ' * (depth + 1)}{_pretty(item, depth + 1)}" for item in obj]
                return f"{open_sym}\n" + ",\n".join(items) + f"\n{'  ' * depth}{close_sym}"

            # For all other types, just return their repr.
            # If debug is True and the object has a __dict__, show that.
            if debug and hasattr(obj, "__dict__"):
                try:
                    return repr(obj.__dict__)
                except Exception:
                    pass
            return repr(obj)

        # Start recursion with the user provided indent level.
        base_indent = '  ' * indent
        pretty_str = _pretty(self, indent)
        # Prepend the base indent to the first line
        return base_indent + pretty_str.replace("\n", "\n" + base_indent)

