def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Dictionary to accumulate all digests seen so far.
    cumulative = {}
    # Record of paths whose digest differs from the one in the root inventory.
    self._diff_digests = {}

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory for version {idx} in '{vdir}'")

        # Load the inventory as a mapping from file path -> digest.
        inv = self._load_inventory(inv_path)  # assumed to return dict

        # Validate that the inventory contains at least all the files seen
        # so far.  If any file is missing, raise an error.
        missing = set(cumulative) - set(inv)
        if missing:
            raise ValueError(
                f"Version {idx} inventory at '{inv_path}' is missing entries for: "
                f"{', '.join(sorted(missing))}"
            )

        # Update the cumulative inventory and check for digest mismatches
        for path, digest in inv.items():
            if path in cumulative:
                if cumulative[path] != digest:
                    # Record a mismatch for later content validation
                    self._diff_digests.setdefault(path, []).append(
                        (digest, cumulative[path])
                    )
            else:
                cumulative[path] = digest

            # Compare with the root inventory
            root_digest = getattr(self, "_root_inventory", {}).get(path)
            if root_digest is not None and root_digest != digest:
                self._diff_digests.setdefault(path, []).append((digest, root_digest))

