def deep_merge_nodes(nodes):
    '''
    Merge duplicate keys in a list of (key_node, value_node) tuples from a ruamel.yaml representation.
    If duplicate keys have MappingNode values, merge them recursively.
    Non-MappingNode duplicates: later value wins.
    '''
    def merge_value(v1, v2):
        # If both are MappingNode, merge recursively
        if isinstance(v1, ruamel.yaml.nodes.MappingNode) and isinstance(v2, ruamel.yaml.nodes.MappingNode):
            merged_pairs = list(v1.value)  # start with existing pairs
            for k_new, v_new in v2.value:
                key = k_new.value
                found = False
                for i, (k_old, v_old) in enumerate(merged_pairs):
                    if k_old.value == key:
                        merged_pairs[i] = (k_old, merge_value(v_old, v_new))
                        found = True
                        break
                if not found:
                    merged_pairs.append((k_new, v_new))
            return ruamel.yaml.nodes.MappingNode(v1.tag, merged_pairs)
        # Otherwise, new value wins
        return v2

    result = []
    key_index = {}  # map key string to index in result list
    for key_node, value_node in nodes:
        key_str = key_node.value
        if key_str in key_index:
            idx = key_index[key_str]
            _, existing_value = result[idx]
            merged_value = merge_value(existing_value, value_node)
            result[idx] = (result[idx][0], merged_value)
        else:
            result.append((key_node, value_node))
            key_index[key_str] = len(result) - 1
    return result

