def deep_merge_nodes(nodes):
    from collections import OrderedDict

    def is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map"

    def merge_mapping(map1, map2):
        """Merge two MappingNode values. map1 and map2 have .value lists of pairs."""
        # Build ordered dict from map1 preserving order and using its key nodes
        merged = OrderedDict()
        for k_node, v_node in getattr(map1, "value", []):
            merged[k_node.value] = (k_node, v_node)
        # Process map2
        for k_node, v_node in getattr(map2, "value", []):
            if k_node.value in merged:
                # replace value but keep original key node
                merged[k_node.value] = (merged[k_node.value][0], v_node)
            else:
                merged[k_node.value] = (k_node, v_node)
        # Construct new mapping node preserving original tag
        new_node = type(map1)(tag=map1.tag, value=list(merged.values()))
        return new_node

    # Main aggregation
    result = OrderedDict()
    for key_node, val_node in nodes:
        key = key_node.value
        if key in result:
            # Merge with existing value
            existing_val_node = result[key][1]
            if is_mapping(existing_val_node) and is_mapping(val_node):
                merged_val = merge_mapping(existing_val_node, val_node)
                result[key] = (result[key][0], merged_val)
            else:
                # Last value wins
                result[key] = (result[key][0], val_node)
        else:
            result[key] = (key_node, val_node)

    return list(result.values())

