def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # If the value itself is None, consider it as representing None.
    if val is None:
        return True
    # Only strings can represent a None value.
    if not isinstance(val, str):
        return False
    # Strip whitespace and compare case-insensitively with common
    # textual representations of None (e.g., 'None', 'null', etc.).
    stripped = val.strip().lower()
    return stripped in ('none', 'null')

