def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    # Try to determine if *seq* is iterable; if not, return it unchanged.
    try:
        iter(seq)
    except TypeError:
        return seq, type(seq)

    # If it is already a sequence (like list, tuple, str, range, etc.), return it as is.
    from collections.abc import Sequence
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # Otherwise, consume it into a list, honoring an optional buffer size.
    import itertools
    if bufsize is None:
        seq = list(seq)
    else:
        seq = list(itertools.islice(seq, bufsize))
    return seq, type(seq)

