def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine number of bins in the histogram
    try:
        nbins = hist.GetNbinsX()
    except AttributeError:
        # fallback to attribute access
        try:
            nbins = len(hist.bins)
        except Exception as exc:
            raise TypeError("Cannot determine number of bins from histogram") from exc

    # Helper to fetch bin content
    def get_content(i):
        try:
            return hist.GetBinContent(i)
        except AttributeError:
            return hist.bins[i]  # assume direct list

    # Helper to fetch bin edge & width
    def get_low_edge(i):
        try:
            return hist.GetBinLowEdge(i)
        except AttributeError:
            return hist.bins[i][0]  # fallback

    def get_width(i):
        try:
            return hist.GetBinWidth(i)
        except AttributeError:
            return hist.bins[i][1]  # fallback

    # Decide coordinate extraction
    if get_coordinate == "left":
        coord_func = lambda i: get_low_edge(i)
    elif get_coordinate == "right":
        coord_func = lambda i: get_low_edge(i) + get_width(i)
    elif get_coordinate == "middle":
        coord_func = lambda i: get_low_edge(i) + 0.5 * get_width(i)
    else:
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    # If make_value not provided, just use bin content
    if make_value is None:
        def make_value(x):
            return (x,)

    points = []
    for i in range(1, nbins + 1):  # ROOT histograms are 1-indexed
        bin_content = get_content(i)
        values = make_value(bin_content)
        if not isinstance(values, tuple) and not isinstance(values, list):
            values = (values,)
        coord = coord_func(i)
        full_point = tuple([coord] + list(values))
        # Ensure point matches field_names length
        if len(full_point) != len(field_names):
            raise ValueError("make_value returned a tuple of length {} but field_names have length {}"
                             .format(len(full_point) - 1, len(field_names)))
        points.append(full_point)

    # Build the graph object (a simple dict here)
    graph = {
        "points": points,
        "field_names": field_names,
        "scale": hist.scale if scale else None,
    }
    return graph

