def determineMetaclass(bases, explicit_mc=None):
    """
    Determine the metaclass for a new-style class from a sequence of bases and an optional
    explicitly supplied metaclass. The return value is a type that will be used as the
    metaclass for the new class.

    Rules:
    1. If an explicit metaclass has been supplied, it is returned after verifying that
       it is a subtype of the metaclass of each base.  If it is not, a TypeError is raised.
    2. If no explicit metaclass is provided, the metaclass is derived from the
       metaclasses of the bases:
          - The metaclass of the most derived metaclass among the bases is chosen.
          - If the bases have conflicting metaclasses that are not related
            by inheritance, a TypeError is raised.
    3. If no bases are supplied, the default metaclass ``type`` is returned.
    """
    # Validate bases
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a type")

    # 1. Explicit metaclass supplied
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a type")
        for base in bases:
            if not issubclass(explicit_mc, type(base)):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__} is not compatible "
                    f"with base class {base.__name__}"
                )
        return explicit_mc

    # 2. No explicit metaclass: infer from bases
    if not bases:
        return type

    # Metaclasses of the bases
    mcs = {type(b) for b in bases}

    # Find a metaclass that is a subclass of all others
    for candidate in mcs:
        if all(issubclass(candidate, other) for other in mcs):
            return candidate

    # No common ancestor metaclass
    raise TypeError(
        f"metaclass conflict: {', '.join(mc.__name__ for mc in mcs)} (no common base)"
    )

