def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # First look for a public message that contains a Diaspora‑specific tag
    try:
        # Some implementations expose a .type or .is_public flag; fall back to payload keys
        if getattr(request, "type", None) == "public":
            if getattr(request, "diaspora", False):
                return True
        if getattr(request, "is_public", False):
            if getattr(request, "diaspora", False):
                return True
        # Some payloads may hide the flag in the data dictionary
        if isinstance(getattr(request, "payload", {}), dict):
            if request.payload.get("message_type") == "public" and request.payload.get("diaspora"):
                return True
    except Exception:
        pass

    # Next, check for a private message with a Diaspora tag
    try:
        if getattr(request, "type", None) == "private":
            if getattr(request, "diaspora", False):
                return True
        if getattr(request, "is_private", False):
            if getattr(request, "diaspora", False):
                return True
        if isinstance(getattr(request, "payload", {}), dict):
            if request.payload.get("message_type") == "private" and request.payload.get("diaspora"):
                return True
    except Exception:
        pass

    # Finally, look for legacy payload patterns
    try:
        payload = getattr(request, "payload", None)
        if isinstance(payload, dict):
            # Legacy systems might wrap the Diaspora fields under a "legacy" key
            if "legacy" in payload:
                legacy = payload["legacy"]
