def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Match http://, https://, ftp:// and www. URLs, excluding trailing punctuation
    url_re = re.compile(
        r'\b(?:(?:https?://|ftp://|www\.)[^\s<>"\'\]\[\\,;!?\)]+)',
        re.IGNORECASE
    )

    def replace_url(match: re.Match) -> str:
        url = match.group(0)
        href = url
        if url.lower().startswith('www.'):
            href = 'http://' + url
        # Preserve the original URL text while making a proper link
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

    return url_re.sub(replace_url, text)

