def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Tags must be non-empty strings of a reasonable length
    if not isinstance(tag, str):
        return False
    if not (1 <= len(tag) <= 30):
        return False

    # First character must be a lowercase letter
    first = tag[0]
    if not first.isalpha() or not first.islower():
        return False

    # Remaining characters may be lowercase letters, digits, hyphens, or underscores
    for ch in tag[1:]:
        if ch.islower() or ch.isdigit() or ch in ("-", "_"):
            continue
        return False

    return True

