def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        return json.loads(document)
    except (json.JSONDecodeError, ValueError):
        pass

    # Treat as XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    # Helper to strip namespace
    def _last_tag(tag):
        return tag.split("}")[-1]

    # Extract subject
    subject_el = root.find(".//{*}Subject")
    subject = subject_el.text if subject_el is not None else None

    # Extract link elements
    links = []
    for link_el in root.findall(".//{*}Link"):
        link_attrs = {k: v for k, v in link_el.attrib.items()}
        link_children = {}
        for child in link_el:
            tag = _last_tag(child.tag)
            link_children[tag] = child.text
        link_entry = {"attributes": link_attrs, **link_children}
        links.append(link_entry)

    # Collect any other top‑level elements (e.g., PublicKey)
    extras = {}
    for child in root:
        tag = _last_tag(child.tag)
        if tag in ("Subject", "Link"):
            continue
        # If the element contains further child elements, convert to dict
        if list(child):
            sub_dict = {}
            for grandchild in child:
                sub_dict[_last_tag(grandchild.tag)] = grandchild.text
            extras[tag] = sub_dict
        else:
            extras[tag] = child.text

    result = {"subject": subject, "links": links}
    result.update(extras)
    return result

