def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle or '@' not in handle:
            return None
        handle = handle.strip()
        acct, domain = handle.split('@', 1)
        resource = f'acct:{handle}'
        encoded_resource = __import__('urllib.parse').quote(resource)
        url = f'https://{domain}/.well-known/webfinger?resource={encoded_resource}'
        # Attempt using requests if available
        try:
            requests = __import__('requests')
            resp = requests.get(url, timeout=5)
            if resp.status_code == 200:
                return resp.text
        except Exception:
            pass
        # Fallback to urllib if requests not available or failed
        try:
            urlopen = __import__('urllib.request').urlopen
            with urlopen(url, timeout=5) as resp:
                data = resp.read()
                return data.decode('utf-8', errors='ignore')
        except Exception:
            pass
    except Exception:
        pass
    return None

