def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    import xml.etree.ElementTree as ET

    def element_to_dict(element):
        """
        Recursively convert an ElementTree element to a nested dictionary.
        Text content is stored under the key "text". Attributes are
        stored under the key "_attributes".
        """
        d = {}
        if element.attrib:
            d["_attributes"] = dict(element.attrib)
        # If the element has child elements, convert them recursively
        children = list(element)
        if children:
            child_dict = {}
            for child in children:
                child_k = child.tag
                child_v = element_to_dict(child)
                # handle repeated tags
                if child_k in child_dict:
                    if not isinstance(child_dict[child_k], list):
                        child_dict[child_k] = [child_dict[child_k]]
                    child_dict[child_k].append(child_v)
                else:
                    child_dict[child_k] = child_v
            d.update(child_dict)
        # If element has text, include it
        text = element.text.strip() if element.text else None
        if text:
            d["text"] = text
        return d

    try:
        if "@' not in handle:
            return {}
        user, host = handle.split('@', 1)
        resource = f"acct:{handle}"
        url = f"https://{host}/.well-known/webfinger?resource={resource}"
