def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import glob

    # Normalize directory list
    if isinstance(settings_dirs, dict):
        dirs = list(settings_dirs.values())
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        dirs = [settings_dirs]

    file_names = []
    for d in dirs:
        if not os.path.isdir(d):
            continue
        pattern = os.path.join(d, spec_option)
        for path in glob.glob(pattern, recursive=True):
            if os.path.isfile(path):
                file_names.append(os.path.basename(path))
    return sorted(file_names)

