    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file specified")
        # Load the YAML file
        try:
            with open(yaml_file, 'r') as f:
                content = f.read()
        except OSError as exc:
            raise IRValidatorException(f"Could not read YAML file '{yaml_file}': {exc}") from exc
        try:
            data = yaml.safe_load(content)
        except Exception as exc:
            raise IRValidatorException(f"Error parsing YAML file '{yaml_file}': {exc}") from exc
        # Ensure the top-level data is a mapping
        if not isinstance(data, dict):
            raise IRValidatorException("YAML content must be a mapping at the top level")
        # Validate required fields (if any are defined on the class)
        required_fields = getattr(cls, 'REQUIRED_FIELDS', None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                missing_str = ', '.join(missing)
                raise IRValidatorException(f"Missing required field(s) in YAML file: {missing_str}")
        return data

