def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    Returns
    -------
    dict
        Dictionary mapping argument names to their resolved default values.
    """
    defaults = {}
    # Get the spec dictionary; if it does not exist, nothing to do.
    spec = getattr(self, "spec", {})
    if not isinstance(spec, dict):
        return defaults

    # First, pull defaults defined directly in the spec
    # The spec may contain two possible structures:
    #   1) a mapping of argument names to a dictionary of properties,
    #      e.g. {"foo": {"default": 42, ...}}
    #   2) a top‑level "defaults" dictionary, e.g. {"defaults": {"foo": 42}}
    if "defaults" in spec and isinstance(spec["defaults"], dict):
        defaults.update(spec["defaults"])
    else:
        for name, attrs in spec.items():
            if isinstance(attrs, dict) and "default" in attrs:
                defaults[name] = attrs["default"]

    # Second, override with any values provided by the instance
    # (e.g., config attributes, environment variables, or user input).
    # These sources are optional; we simply check for common patterns.
    for name in list(defaults):
        # Config source (assumes a `config` attribute with an `options` dict).
        config = getattr(self, "config", None)
        if config is not None:
            options = getattr(config, "options", {})
            if name in options:
                defaults[name] = options[name]
                continue

        # Attribute source (assumes the instance may have an attribute named
        # exactly the same as the argument name).
        if hasattr(self, name):
            defaults[name] = getattr(self, name)
            continue

        # Environment variable source (uppercase variant of the name).
        try:
            env = os.environ
        except Exception:
            env = {}
        env_name = name.upper()
        if env_name in env:
            defaults[name] = env[env_name]
            continue

    return defaults

