def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (expected to be a mapping).
    :raises TypeError: If args is not a mapping.
    :raises ValueError: If any argument value is not among the allowed choices.
    """
    # Ensure the arguments are in a mapping form
    if not isinstance(args, dict):
        raise TypeError("Arguments must be provided as a dictionary")

    # Retrieve the mapping of allowed choices from the instance
    allowed_choices = getattr(self, "choices", {})

    # Iterate over each argument provided
    for arg_name, arg_value in args.items():
        # If the argument has defined choices, validate it
        if arg_name in allowed_choices:
            valid_set = set(allowed_choices[arg_name])

            # Support single value or iterable of values
            if isinstance(arg_value, (list, tuple, set)):
                for val in arg_value:
                    if val not in valid_set:
                        raise ValueError(
                            f"Invalid value '{val}' for argument '{arg_name}'. "
                            f"Allowed choices are: {sorted(valid_set)}"
                        )
            else:
                if arg_value not in valid_set:
                    raise ValueError(
                        f"Invalid value '{arg_value}' for argument '{arg_name}'. "
                        f"Allowed choices are: {sorted(valid_set)}"
                    )
    # No return needed; method either passes silently or raises an exception.

