    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated vars_dict
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        # No extra vars to merge
        if not extra_vars:
            return vars_dict

        # Helper to apply a key/value pair to vars_dict
        def _apply_to_dict(key, value):
            if not isinstance(key, str):
                raise TypeError(f"key must be a string, got {type(key)!r}")
            vars_dict[key] = value

        # If extra_vars is a dict, update in one go
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # If it's an iterable, iterate over items
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be dict or iterable")

        for item in iterator:
            # Item could be a dict containing a single mapping
            if isinstance(item, dict):
                vars_dict.update(item)
            # Tuple or list of length 2
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                _apply_to_dict(key, value)
            # String of form key=value
            elif isinstance(item, str):
                if "=" not in item:
                    raise ValueError(f"Invalid extra-var string '{item}': expected 'key=value'")
                key, value = item.split("=", 1)
                # Strip whitespace around key and value
                key = key.strip()
                value = value.strip()
                _apply_to_dict(key, value)
            else:
                raise TypeError(f"Unsupported extra-var type: {type(item)!r}")
        return vars_dict

