def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json

    # Build base command
    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        try:
            v = int(verbose)
            if v < 0:
                v = 0
        except Exception:
            v = 1
        cmd.append("-" + "v" * v)

    # Handle ansible_args (e.g., {"check": True, "diff": False, "forks": 10})
    if ansible_args:
        for key, value in ansible_args.items():
            # Skip None values
            if value is None:
                continue
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
                # if False, skip flag
            else:
                cmd.extend([flag, str(value)])

    # Handle extra_vars
    if extra_vars:
        # ansible expects extra-vars as a JSON string or key=value string
        # We will pass it as a JSON string
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook executable not found")

    # Log output
    if ir_plugin:
        if result.stdout:
            ir_plugin.log(level="info", msg=result.stdout.strip())
        if result.stderr:
            ir_plugin.log(level="error", msg=result.stderr.strip())

    # Raise on error
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook exited with code {result.returncode}"
            f"\nstdout:\n{result.stdout}\nstderr:\n{result.stderr}"
        )

    return result.stdout.strip()

