def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc.
        :param values_dict: The dict of with arguments.
        :return: The modified values_dict.
        """
        for key, value in list(values_dict.items()):
            if value is None:
                continue
            # string values only go through conversion
            if not isinstance(value, str):
                continue
            v = value.strip()
            # Boolean conversion
            lower_v = v.lower()
            if lower_v in ("true", "false"):
                values_dict[key] = lower_v == "true"
                continue
            # Numeric conversion
            try:
                if '.' in v:
                    values_dict[key] = float(v)
                else:
                    values_dict[key] = int(v)
                continue
            except ValueError:
                pass
            # List conversion (comma separated)
            if ',' in v:
                parts = [p.strip() for p in v.split(',')]
                converted_parts = []
                for part in parts:
                    if not part:
                        converted_parts.append(part)
                        continue
                    part_lower = part.lower()
                    if part_lower in ("true", "false"):
                        converted_parts.append(part_lower == "true")
                        continue
                    try:
                        if '.' in part:
                            converted_parts.append(float(part))
                        else:
                            converted_parts.append(int(part))
                    except ValueError:
                        converted_parts.append(part)
                values_dict[key] = converted_parts
                continue
        return values_dict

