                    if part_lower in ("true", "false"):
                        converted_parts.append(part_lower == "true")
                        continue
                    try:
                        if '.' in part:
                            converted_parts.append(float(part))
                        else:
                            converted_parts.append(int(part))
                    except ValueError:
                        converted_parts.append(part)
                values_dict[key] = converted_parts
                continue
        return values_dict

