    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Determine the plugin specification file
    plugin_file = None
    for fname in ("plugin.yaml", "plugin.yml", "spec.yaml", "spec.yml", "plugin.json"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            plugin_file = path
            break

    if not plugin_file:
        return {}

    # Load the spec
    with open(plugin_file, "r", encoding="utf-8") as f:
        if plugin_file.endswith(".json"):
            spec = json.load(f)
        else:
            if yaml is None:
                raise RuntimeError("yaml module not available")
            spec = yaml.safe_load(f)

    # Flatten nested structures
    def _flatten(obj, parent_key=""):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                items.update(_flatten(v, new_key))
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                items.update(_flatten(item, new_key))
        else:
            items[parent_key] = obj
        return items

    return _flatten(spec)

